    fmt.Fprintf(os.Stdout, "Vector has %d(%d) entries: {", p.size, p.cap);
    for i = 0; i < p.size; i++ {
        fmt.Fprintf(os.Stdout, " %d", p.data[i]);
    }
    fmt.Fprintf(os.Stdout, " }\n");
}

